  ["You are not in a guild, so there is nothing to link: /guilded verify connects guild members to their guild's Discord. Everything else in Guilded works without a guild or Discord."] = "Vous n'\195\170tes pas dans une guilde, il n'y a donc rien \195\160 lier : /guilded verify relie les membres d'une guilde au Discord de leur guilde. Tout le reste de Guilded fonctionne sans guilde ni Discord.",
  ["Your Discord link code was removed from this WoW account."] = "Votre code de lien Discord a \195\169t\195\169 retir\195\169 de ce compte WoW.",
  ["Saved. All your characters on this WoW account will link to your Discord by themselves the next time a guildmate's Guilded companion syncs, and Discord will message you. Nothing else to do, also for your alts."] = "Enregistr\195\169. Tous vos personnages de ce compte WoW se lieront tout seuls \195\160 votre Discord \195\160 la prochaine synchro du compagnon Guilded d'un membre de la guilde, et Discord vous enverra un message. Rien d'autre \195\160 faire, aussi pour vos alts.",
  ["That code does not look right. In Discord, use /character pair and copy the whole /guilded verify line."] = "Ce code ne semble pas correct. Sur Discord, utilisez /character pair et copiez toute la ligne /guilded verify.",
