  ["Your companion is connected, so Guilded now uses your Discord standings. /guilded setup local switches back."] = "Votre compagnon est reli\195\169 : Guilded utilise maintenant vos classements Discord. /guilded setup local pour revenir en arri\195\168re.",
  ["Your companion is sending Discord standings. To use them in game: /guilded setup connected"] = "Votre compagnon envoie les classements Discord. Pour les utiliser en jeu : /guilded setup connected",
  ["In-game only: gear checks, dungeon recording, raid attendance and loot tools work without Discord or signups. Officers can share local standings with online guildmates.\n\nConnected: optional companion sync adds Discord rosters, signups and verified season scores.\n\nData stays in SavedVariables. Keep backups. This choice preserves existing rosters and points; it does not stop a running companion. Change it any time with /guilded setup."] = "En jeu : equipement, suivi des donjons, presences et butin sans Discord ni inscriptions. Les officiers peuvent partager le classement avec les membres connectes.\n\nConnecte : le compagnon ajoute rosters Discord, inscriptions et scores saisonniers verifies.\n\nLes donnees restent dans SavedVariables. Faites des sauvegardes. Ce choix conserve les rosters et points existants et ne ferme pas le compagnon. Modifiez-le avec /guilded setup.",
  ["Local changes are waiting. Save with /reload or log out. No companion is required."] = "Modifications locales en attente. Sauvegardez avec /reload ou en vous deconnectant. Aucun compagnon requis.",
  ["Your data is saved on this PC. No Discord connection is required. Keep a backup of SavedVariables."] = "Vos donnees sont sur ce PC. Discord est facultatif. Gardez une sauvegarde de SavedVariables.",
  ["Save your local data with /reload or by logging out. Online sync is optional."] = "Sauvegardez avec /reload ou en vous deconnectant. La synchronisation en ligne est facultative.",
