  ["Guilded will announce your milestones (levels, first dungeon clears, PvP and duel milestones) in guild chat. Type /guilded announce off to stop, or turn types off in Settings."] = "Guilded k\195\188ndigt deine Meilensteine (Stufen, erste Dungeons, PvP- und Duell-Meilensteine) im Gildenchat an. Mit /guilded announce off stoppst du das, oder schalte Arten in den Einstellungen ab.",
  ["Guilded's messages in their own chat tab"] = "Guilded-Nachrichten in einem eigenen Chatreiter",
  ["Guildmates are hidden from your maps."] = "Gildenmitglieder sind auf deinen Karten ausgeblendet.",
  ["Open your world map (%s) to see guildmates."] = "\195\150ffne deine Weltkarte (%s), um Gildenmitglieder zu sehen.",
