  ["Hide minimap button"] = "Minikartenknopf ausblenden",
  ["Hide the live timer without stopping fight recording or results."] = "Live-Timer ausblenden, ohne Kampfaufzeichnung oder Ergebnisse zu stoppen.",
  ["high"] = "hoch",
  ["Highest priority: %s. Confirm the item is usable and tradable, then /guilded council award."] = "H\195\182chste Priorit\195\164t: %s. Pr\195\188fe Nutzbarkeit und Handelbarkeit, dann /guilded council award.",
  ["Highest roll wins. A tie rolls again between the tied players. Just for fun, no gold."] = "Der h\195\182chste Wurf gewinnt. Bei Gleichstand w\195\188rfeln nur die gleichstehenden Spieler erneut. Nur zum Spa\195\159, ohne Gold.",
  ["Historical rules: 100 per distinct dungeon, no speed bonus."] = "Historische Regeln: 100 pro unterschiedlichem Dungeon, kein Tempobonus.",
