  ["Imported %d reserve(s) for %d player(s). The list is open and shared with the guild; lock it when the raid starts."] = "%d Reservierung(en) f\195\188r %d Spieler importiert. Die Liste ist offen und mit der Gilde geteilt; sperre sie zum Raidstart.",
  ["Imported GRM source history; not Guilded attendance or ownership."] = "Importierter GRM-Quellverlauf; keine Guilded-Anwesenheits- oder Eigentumsdaten.",
  ["Imported loot history"] = "Importierter Beuteverlauf",
  ["Imported loot history - source records, not Guilded points"] = "Importierter Beuteverlauf - Quelldaten, keine Guilded-Punkte",
  ["Imported That's My BiS priorities for %d item(s). Item tooltips show them."] = "That's-My-BiS-Priorit\195\164ten f\195\188r %d Gegenst\195\164nde importiert. Sie erscheinen in Gegenstands-Tooltips.",
  ["Imported."] = "Importiert.",
  ["In Discord, use /character pair, copy the /guilded verify line it shows and paste it here."] = "Nutze in Discord /character pair, kopiere die angezeigte Zeile mit /guilded verify und f\195\188ge sie hier ein.",
  ["in the calendar"] = "im Kalender",
  ["In-game only (default)"] = "Nur im Spiel (Standard)",
  ["In-game only selected. Your saved data and guild permissions are preserved."] = "Nur im Spiel ausgew\195\164hlt. Gespeicherte Daten und Gildenberechtigungen bleiben erhalten.",
  ["In-game only: gear checks, dungeon recording, raid attendance and loot tools work without Discord or signups. Officers can share local standings with online guildmates.\n\nConnected: optional companion sync adds Discord rosters, signups and verified season scores.\n\nData stays in SavedVariables. Keep backups. This choice preserves existing rosters and points; it does not stop a running companion. Change it any time with /guilded setup."] = "Nur im Spiel: Ausr\195\188stungschecks, Dungeon-Aufzeichnung, Raidanwesenheit und Beutewerkzeuge funktionieren ohne Discord oder Anmeldungen. Offiziere k\195\182nnen lokale Ranglisten mit Gildenmitgliedern teilen, die online sind.\n\nVerbunden: Die optionale Companion-Synchronisierung erg\195\164nzt Discord-Kader, Anmeldungen und gepr\195\188fte Saisonwertungen.\n\nDaten bleiben in SavedVariables. Bewahre Sicherungen auf. Diese Auswahl erh\195\164lt vorhandene Kader und Punkte; sie beendet keinen laufenden Companion. Mit /guilded setup jederzeit \195\164ndern.",
  ["Incoming map messages: %d, positions %d, ignored %d; last %s."] = "Empfangene Kartennachrichten: %d, Positionen %d, ignoriert %d; zuletzt %s.",
  ["Instances automatically mark you busy. Reports pause in combat. Location is never shared."] = "Instanzen setzen dich automatisch auf besch\195\164ftigt. Meldungen pausieren im Kampf. Dein Standort wird nie geteilt.",
  ["Intellect"] = "Intelligenz",
  ["Invalid action, name or note (31 bytes maximum)."] = "Ung\195\188ltige Aktion, Name oder Notiz (h\195\182chstens 31 Bytes).",
  ["invalid coordinates"] = "ung\195\188ltige Koordinaten",
  ["Invalid or oversized GRM archive."] = "Ung\195\188ltiges oder zu gro\195\159es GRM-Archiv.",
  ["invalid payload"] = "ung\195\188ltige Nutzdaten",
  ["invited"] = "eingeladen",
  ["Issues"] = "Probleme",
  ["It checks by itself when a ready check starts: every Guilded reports what it carries. Hover a row for details; a question mark means the game hides it."] = "Automatische Pr\195\188fung bei einem Bereitschaftscheck: Jedes Guilded meldet die eigene Ausr\195\188stung. Fahre f\195\188r Details \195\188ber eine Zeile; ein Fragezeichen bedeutet, dass das Spiel die Daten verbirgt.",
