  ["Join a party or raid before starting a loot roll."] = "Tritt einer Gruppe oder einem Raid bei, bevor du Beutew\195\188rfeln startest.",
  ["Join a raid or party first."] = "Tritt zuerst einem Raid oder einer Gruppe bei.",
  ["Join your in-game guild before enabling the officer bridge."] = "Tritt deiner Gilde im Spiel bei, bevor du die Offiziersanbindung aktivierst.",
  ["joined"] = "beigetreten",
  ["Just asked; wait %d seconds."] = "Gerade erst angefragt; warte %d Sekunden.",
  ["Keeps source history locally. Does not alter guild notes, ranks, points or Discord links."] = "Bewahrt den Quellverlauf lokal auf. \195\132ndert keine Gildennotizen, R\195\164nge, Punkte oder Discord-Verkn\195\188pfungen.",
  ["Keeps the in-game guild message of the day current from an officer's game. Off by default; a manual edit pauses it."] = "H\195\164lt die Gildennachricht des Tages \195\188ber das Spiel eines Offiziers aktuell. Standardm\195\164\195\159ig aus; eine manuelle \195\132nderung pausiert sie.",
  ["Known local and shared characters"] = "Bekannte lokale und geteilte Charaktere",
