  ["Ledger sync is off. An officer turns it on with /guilded ledgersync on."] = "Kassenbuch-Sync ist aus. Ein Offizier aktiviert ihn mit /guilded ledgersync on.",
  ["Ledger sync is off. Entries already received stay."] = "Kassenbuch-Sync ist aus. Bereits empfangene Eintr\195\164ge bleiben erhalten.",
