  ["Prepares the guild message of the day from an officer's game: one click on a button updates it (the game does not allow it automatically). Off by default; a manual edit pauses it."] = "Bereitet die Gildennachricht des Tages vom Spiel eines Offiziers aus vor: Ein Klick auf eine Schaltfl\195\164che aktualisiert sie (das Spiel erlaubt es nicht automatisch). Standardm\195\164\195\159ig aus; eine manuelle \195\132nderung pausiert sie.",
