  ["Save your local data with /reload or by logging out. Online sync is optional."] = "Speichere lokale Daten mit /reload oder durch Ausloggen. Online-Synchronisierung ist optional.",
  ["Saved in game. Type /reload or log out to let your companion upload it. Discord validates the run and awards points."] = "Im Spiel gespeichert. Nutze /reload oder logge dich aus, damit dein Companion hochladen kann. Discord pr\195\188ft den Lauf und vergibt Punkte.",
  ["Saved in game. Type /reload or log out, then let your paired companion sync. Upload and public listing are not confirmed here."] = "Im Spiel gespeichert. Nutze /reload oder logge dich aus und lasse den verkn\195\188pften Companion synchronisieren. Upload und \195\182ffentliche Auflistung werden hier nicht best\195\164tigt.",
  ["Saved plans: "] = "Gespeicherte Pl\195\164ne: ",
  ["Saved. All your characters on this WoW account will link to your Discord by themselves the next time a guildmate's Guilded companion syncs, and Discord will message you. Nothing else to do, also for your alts."] = "Gespeichert. Alle Charaktere dieses WoW-Accounts werden automatisch mit deinem Discord verkn\195\188pft, sobald der Guilded-Companion eines Gildenmitglieds synchronisiert. Discord benachrichtigt dich. Auch f\195\188r deine Twinks ist nichts weiter n\195\182tig.",
  ["Saves the loot system for the selected core."] = "Speichert das Beutesystem der ausgew\195\164hlten Stammgruppe.",
  ["Saves the raid name with the selected raid core. Next time, type that name and Start raid."] = "Speichert den Raidnamen mit der gew\195\164hlten Stammgruppe. Gib beim n\195\164chsten Mal den Namen ein und starte den Raid.",
  ["Saving on this PC"] = "Auf diesem PC speichern",
  ["Say your milestones (levels, first dungeon clears, honorable kills, duel wins) once in guild chat so guildmates can cheer. On by default; untick to turn them off."] = "Sage deine Meilensteine (Stufen, erste Dungeon-Abschl\195\188sse, ehrenvolle Siege, Duellsiege) einmal im Gildenchat an, damit deine Gildenmitglieder jubeln k\195\182nnen. Standardm\195\164\195\159ig an; Haken entfernen zum Ausschalten.",
  ["Say your milestones in guild chat (on by default)."] = "Sage deine Meilensteine im Gildenchat an (standardm\195\164\195\159ig an).",
  ["Scan the calendar"] = "Kalender einlesen",
  ["Scenario at level %d (party maximum)."] = "Szenario auf Stufe %d (Gruppenmaximum).",
  ["Scenario only: final-boss evidence and 80% presence required. No confirmation yet."] = "Nur ein Szenario: Nachweis des letzten Bosses und 80% Anwesenheit erforderlich. Noch keine Best\195\164tigung.",
