  ["Soft reserves: players reserve items before the raid; when one drops, its reservers roll (SR = how many each)."] = "Soft-Reserves: Spieler reservieren Gegenst\195\164nde vor dem Raid; beim Fund w\195\188rfeln die Reservierenden (SR = Anzahl pro Spieler).",
