  ["Sync next missing event"] = "N\195\164chstes fehlendes Ereignis synchronisieren",
  ["Sync your companion for improvement scenarios and role details."] = "Synchronisiere deinen Companion f\195\188r Verbesserungsszenarien und Rollendetails.",
  ["System"] = "System",
  ["Tab"] = "Reiter",
  ["Takes back the last EP/GP entry you made (it stays in the ledger, marked voided). Click twice."] = "Nimmt deinen letzten EP/GP-Eintrag zur\195\188ck (bleibt als ung\195\188ltig markiert im Kassenbuch). Zweimal klicken.",
  ["Takes GP back, for example a mistaken charge or a returned item. Never below 0."] = "Nimmt GP zur\195\188ck, etwa bei einer falschen Berechnung oder zur\195\188ckgegebener Beute. Nie unter 0.",
  ["Takes the typed character off the selected core. Click twice to confirm."] = "Entfernt den eingegebenen Charakter aus der ausgew\195\164hlten Stammgruppe. Zweimal zum Best\195\164tigen klicken.",
  ["Talents, level, chosen blessings and party range affect coverage. Hidden or offline auras remain unknown."] = "Talente, Stufe, gew\195\164hlte Segen und Gruppenreichweite beeinflussen die Abdeckung. Verborgene oder Offline-Auren bleiben unbekannt.",
  ["Tank"] = "Tank",
