  ["Target"] = "Ziel",
  ["Target %s / time %s\nTime rating %d (50-400) / level penalty %d%%\nProvisional public estimate; guild rules may differ."] = "Zielzeit %s / Zeit %s\nZeitwertung %d (50-400) / Stufenabzug %d%%\nVorl\195\164ufige \195\182ffentliche Sch\195\164tzung; Gildenregeln k\195\182nnen abweichen.",
  ["Target not calibrated"] = "Zielzeit nicht kalibriert",
  ["Templates"] = "Vorlagen",
  ["Test dungeon run"] = "Test-Dungeon-Lauf",
  ["Test dungeon run saved (%d:%02d, you + %s). /reload so the companion sends it; an officer runs /import apply. /guilded sim clear removes it here, /setup testraid cleanup in Discord."] = "Testdungeon gespeichert (%d:%02d, du + %s). /reload zum Senden mit dem Companion; ein Offizier nutzt /import apply. /guilded sim clear entfernt ihn hier, /setup testraid cleanup in Discord.",
  ["Test tools"] = "Testwerkzeuge",
  ["Test tools (fake players, nothing reaches Discord)"] = "Testwerkzeuge (erfundene Spieler, nichts erreicht Discord)",
  ["Test tools (fake players; saved tests can sync to Discord)"] = "Tests (fiktive Spieler; gespeicherte Tests k\195\182nnen Discord erreichen)",
  ["That code does not look right. In Discord, use /character pair and copy the whole /guilded verify line."] = "Dieser Code scheint nicht zu stimmen. Nutze in Discord /character pair und kopiere die gesamte Zeile mit /guilded verify.",
  ["That core exists, or the limit of 20 cores was reached."] = "Die Stammgruppe existiert bereits oder das Limit von 20 Stammgruppen ist erreicht.",
  ["That export could not be read. Copy it again, all of it."] = "Export konnte nicht gelesen werden. Kopiere ihn erneut und vollst\195\164ndig.",
  ["That export could not be unpacked. Copy it again, all of it."] = "Export konnte nicht entpackt werden. Kopiere ihn erneut und vollst\195\164ndig.",
  ["That name could not be added: check the spelling (no links), or the 80-player limit."] = "Name konnte nicht hinzugef\195\188gt werden: Pr\195\188fe Schreibweise (keine Links) oder das Limit von 80 Spielern.",
