  ["The calendar has not been read yet: press Scan."] = "Der Kalender wurde noch nicht gelesen: Klicke auf Einlesen.",
  ["The first line must be the CSV header (with ItemId and Name)."] = "Die erste Zeile muss die CSV-Kopfzeile sein (mit ItemId und Name).",
  ["The game rejected the request. Preview again."] = "Das Spiel hat die Anfrage abgelehnt. Erstelle erneut eine Vorschau.",
  ["the guild's default"] = "Gildenstandard",
  ["The lowest roll is out. The next round rolls up to that lowest number. Last one left wins. Just for fun, no gold."] = "Der niedrigste Wurf scheidet aus. In der n\195\164chsten Runde wird bis zu dieser niedrigsten Zahl gew\195\188rfelt. Der letzte verbleibende Spieler gewinnt. Nur zum Spa\195\159, ohne Gold.",
  ["The options page is not ready yet."] = "Die Optionsseite ist noch nicht bereit.",
  ["The plan has no actions."] = "Der Plan enth\195\164lt keine Aktionen.",
  ["The prospect list is full; remove old entries first."] = "Die Bewerberliste ist voll; entferne zuerst alte Eintr\195\164ge.",
  ["the run being recorded, points"] = "aktueller aufgezeichneter Lauf, Punkte",
  ["Then each rolls up to the number the other got (rolled 57? type /roll 57). Whoever rolls 1 loses. Just for fun, no gold."] = "Dann w\195\188rfelt jeder bis zur Zahl des anderen (57 gew\195\188rfelt? Nutze /roll 57). Wer 1 w\195\188rfelt, verliert. Nur zum Spa\195\159, ohne Gold.",
  ["They come from the Discord bot through an officer's addon. Check back after the next raid."] = "Die Daten kommen vom Discord-Bot \195\188ber das Addon eines Offiziers. Schau nach dem n\195\164chsten Raid erneut nach.",
  ["This action is unavailable on this client."] = "Diese Aktion ist auf diesem Client nicht verf\195\188gbar.",
  ["This code excludes per-character imported loot history. Back up the character's SavedVariables/Guilded.lua file separately."] = "Dieser Code enth\195\164lt keinen importierten Beuteverlauf pro Charakter. Sichere die Datei SavedVariables/Guilded.lua des Charakters separat.",
  ["This game client cannot change the guild message from an addon, so nothing is written."] = "Dieser Spielclient erlaubt es einem Addon nicht, die Gildennachricht zu \195\164ndern, daher wird nichts geschrieben.",
  ["This game client cannot create calendar events for addons."] = "Dieser Spielclient erlaubt Addons keine Kalendertermine.",
  ["This game client cannot prepare the guild message command (/gmotd), so nothing is offered."] = "Dieser Spielclient kann den Gildennachrichten-Befehl (/gmotd) nicht vorbereiten, daher wird nichts angeboten.",
  ["This game client cannot unpack that export. Paste the CSV export instead."] = "Dieser Spielclient kann den Export nicht entpacken. F\195\188ge stattdessen den CSV-Export ein.",
