  ["You won %s for %s GP."] = "Du hast %s f\195\188r %s GP gewonnen.",
  ["Your addon shares supported data with online guildmates. An officer handles Discord sync; personal sync is optional."] = "Dein Addon teilt unterst\195\188tzte Daten mit Gildenmitgliedern, die online sind. Ein Offizier \195\188bernimmt die Discord-Synchronisierung; pers\195\182nliche Synchronisierung ist optional.",
