  ["Your character is missing from the roster."] = "Dein Charakter fehlt im Kader.",
  ["Your companion is connected, so Guilded now uses your Discord standings. /guilded setup local switches back."] = "Dein Companion ist verbunden, daher nutzt Guilded jetzt deine Discord-Wertungen. /guilded setup local stellt es zur\195\188ck.",
  ["Your companion is sending Discord standings. To use them in game: /guilded setup connected"] = "Dein Companion sendet Discord-Wertungen. Um sie im Spiel zu nutzen: /guilded setup connected",
  ["Your data is saved on this PC. No Discord connection is required. Keep a backup of SavedVariables."] = "Deine Daten sind auf diesem PC gespeichert. Discord ist nicht erforderlich. Sichere SavedVariables regelm\195\164\195\159ig.",
  ["Your data reaches Discord after you /reload or log out (an officer's companion sends it)."] = "Deine Daten erreichen Discord nach /reload oder dem Ausloggen (ein Offiziers-Companion sendet sie).",
  ["Your Discord link code is saved: your characters link by themselves. /guilded verify off removes it."] = "Dein Discord-Verkn\195\188pfungscode ist gespeichert: Deine Charaktere werden automatisch verkn\195\188pft. /guilded verify off entfernt den Code.",
