  ["Relayed: %d items received from guildmates, %d passed on; %d dungeon confirmations heard, %d sent."] = "Weitergeleitet: %d Eintr\195\164ge von Gildenmitgliedern erhalten, %d weitergegeben; %d Dungeon-Best\195\164tigungen erhalten, %d gesendet.",
