  ["Nothing from Discord yet. The board fills in after your companion syncs, or when a guildmate who has it shares it."] = "Noch nichts aus Discord. Das Brett f\195\188llt sich nach der Synchronisierung deines Begleiters oder wenn ein Gildenmitglied, das es hat, es teilt.",
  ["One vote each, you can change it. %d member(s) voted."] = "Eine Stimme pro Person, \195\164nderbar. %d Mitglied(er) haben abgestimmt.",
  ["Only officers can post guild news."] = "Nur Offiziere k\195\182nnen Gildenneuigkeiten posten.",
  ["Pick up to %d. %d member(s) voted."] = "Bis zu %d w\195\164hlen. %d Mitglied(er) haben abgestimmt.",
