  ["Use /guilded board vote <poll number> <option number> (see /guilded board)."] = "Nutze /guilded board vote <Umfragenummer> <Optionsnummer> (siehe /guilded board).",
  ["Vote saved. Your companion sends it to Discord with your next sync (or a guildmate's does)."] = "Stimme gespeichert. Dein Begleiter sendet sie bei der n\195\164chsten Synchronisierung an Discord (oder der eines Gildenmitglieds).",
