  ["%d craft order(s) from Discord you can make: the Orders page of the Guilded window (/guilded orders)."] = "%d Handwerksauftrag/-auftr\195\164ge aus Discord, die du herstellen kannst: Seite Auftr\195\164ge im Guilded-Fenster (/guilded orders).",
