  ["Guilded will announce your milestones (levels, first dungeon clears, PvP and duel milestones) in guild chat. Type /guilded announce off to stop, or turn types off in Settings."] = "Guilded anunciar\195\161 tus hitos (niveles, primeras mazmorras, hitos de JcJ y de duelos) en el chat de hermandad. Escribe /guilded announce off para detenerlo, o desactiva tipos en los ajustes.",
