  ["Guildmates show on your maps."] = "Los miembros aparecen en tus mapas.",
  ["Guildmates who know the recipe (from their own addon)."] = "Miembros que conocen la receta (seg\195\186n su propio addon).",
  ["Healer"] = "Sanador",
  ["HEALER"] = "SANADOR",
  ["Here:"] = "Presentes:",
  ["Hide minimap button"] = "Ocultar bot\195\179n del minimapa",
  ["Hide the live timer without stopping fight recording or results."] = "Oculta el cron\195\179metro en directo sin detener la grabaci\195\179n del combate ni los resultados.",
  ["high"] = "alta",
  ["Highest priority: %s. Confirm the item is usable and tradable, then /guilded council award."] = "Mayor prioridad: %s. Comprueba que el objeto se puede usar e intercambiar, luego /guilded council award.",
  ["Highest roll wins. A tie rolls again between the tied players. Just for fun, no gold."] = "Gana la tirada m\195\161s alta. En caso de empate, vuelven a tirar solo los empatados. Solo por diversi\195\179n, sin oro.",
