  ["Imported %d reserve(s) for %d player(s). The list is open and shared with the guild; lock it when the raid starts."] = "%d reserva(s) importadas para %d jugador(es). La lista est\195\161 abierta y compartida con la hermandad; bloqu\195\169ala al empezar la banda.",
