  ["Keeps the in-game guild message of the day current from an officer's game. Off by default; a manual edit pauses it."] = "Mantiene al d\195\173a el mensaje del d\195\173a de la hermandad desde el juego de un oficial. Desactivado por defecto; una edici\195\179n manual lo pausa.",
  ["Known local and shared characters"] = "Personajes locales y compartidos conocidos",
