  ["Links all your characters on this WoW account. A guildmate's Guilded companion passes the code on when it next syncs."] = "Vincula todos tus personajes de esta cuenta de WoW. El acompa\195\177ante Guilded de un miembro de la hermandad pasa el c\195\179digo en su pr\195\179xima sincronizaci\195\179n.",
