  ["Talents, level, chosen blessings and party range affect coverage. Hidden or offline auras remain unknown."] = "Los talentos, el nivel, las bendiciones elegidas y el alcance del grupo afectan a la cobertura. Las auras ocultas o de jugadores desconectados siguen siendo desconocidas.",
