  ["Templates"] = "Plantillas",
  ["Test dungeon run"] = "Mazmorra de prueba",
  ["Test dungeon run saved (%d:%02d, you + %s). /reload so the companion sends it; an officer runs /import apply. /guilded sim clear removes it here, /setup testraid cleanup in Discord."] = "Mazmorra de prueba guardada (%d:%02d, t\195\186 + %s). /reload para enviarla con el Companion; un oficial usa /import apply. /guilded sim clear la elimina aqu\195\173, /setup testraid cleanup en Discord.",
  ["Test tools"] = "Herramientas de prueba",
  ["Test tools (fake players, nothing reaches Discord)"] = "Herramientas de prueba (jugadores ficticios, no se env\195\173a nada a Discord)",
  ["Test tools (fake players; saved tests can sync to Discord)"] = "Pruebas (jugadores ficticios; pueden sincronizarse con Discord)",
  ["That code does not look right. In Discord, use /character pair and copy the whole /guilded verify line."] = "Ese c\195\179digo no parece correcto. Usa /character pair en Discord y copia toda la l\195\173nea de /guilded verify.",
  ["That core exists, or the limit of 20 cores was reached."] = "Ese equipo ya existe o se ha alcanzado el l\195\173mite de 20 equipos.",
  ["That export could not be read. Copy it again, all of it."] = "No se pudo leer esa exportaci\195\179n. C\195\179piala otra vez, entera.",
  ["That export could not be unpacked. Copy it again, all of it."] = "No se pudo descomprimir esa exportaci\195\179n. C\195\179piala otra vez, entera.",
  ["That name could not be added: check the spelling (no links), or the 80-player limit."] = "No se pudo a\195\177adir ese nombre: revisa la escritura (sin enlaces) o el l\195\173mite de 80 jugadores.",
