  ["The calendar has not been read yet: press Scan."] = "A\195\186n no se ha le\195\173do el calendario: pulsa Leer.",
  ["The first line must be the CSV header (with ItemId and Name)."] = "La primera l\195\173nea debe ser la cabecera CSV (con ItemId y Name).",
  ["The game rejected the request. Preview again."] = "El juego ha rechazado la solicitud. Previsualiza de nuevo.",
  ["the guild's default"] = "predeterminado de la hermandad",
  ["The lowest roll is out. The next round rolls up to that lowest number. Last one left wins. Just for fun, no gold."] = "Se elimina la tirada m\195\161s baja. La siguiente ronda tiene como m\195\161ximo ese n\195\186mero. Gana el \195\186ltimo que quede. Solo por diversi\195\179n, sin oro.",
  ["The options page is not ready yet."] = "La p\195\161gina de opciones a\195\186n no est\195\161 lista.",
  ["The plan has no actions."] = "El plan no contiene acciones.",
  ["The prospect list is full; remove old entries first."] = "La lista de candidatos est\195\161 llena; elimina entradas antiguas primero.",
  ["the run being recorded, points"] = "recorrido que se est\195\161 grabando, puntos",
  ["Then each rolls up to the number the other got (rolled 57? type /roll 57). Whoever rolls 1 loses. Just for fun, no gold."] = "Despu\195\169s, cada uno tira hasta el n\195\186mero del otro (\194\191ha sacado 57? Usa /roll 57). Pierde quien saque 1. Solo por diversi\195\179n, sin oro.",
  ["They come from the Discord bot through an officer's addon. Check back after the next raid."] = "Llegan desde el bot de Discord mediante el addon de un oficial. Vuelve a consultar despu\195\169s de la pr\195\179xima banda.",
  ["This action is unavailable on this client."] = "Esta acci\195\179n no est\195\161 disponible en este cliente.",
  ["This code excludes per-character imported loot history. Back up the character's SavedVariables/Guilded.lua file separately."] = "Este c\195\179digo no incluye el historial de bot\195\173n importado del personaje. Guarda por separado su archivo SavedVariables/Guilded.lua.",
  ["This game client cannot change the guild message from an addon, so nothing is written."] = "Este cliente de juego no permite que un addon cambie el mensaje de hermandad, as\195\173 que no se escribe nada.",
  ["This game client cannot create calendar events for addons."] = "Este cliente no permite que los addons creen eventos de calendario.",
  ["This game client cannot prepare the guild message command (/gmotd), so nothing is offered."] = "Este cliente de juego no puede preparar el comando del mensaje de hermandad (/gmotd), as\195\173 que no se ofrece nada.",
  ["This game client cannot unpack that export. Paste the CSV export instead."] = "Este cliente no puede descomprimir esa exportaci\195\179n. Pega la exportaci\195\179n CSV.",
