  ["Your Discord link code is saved: your characters link by themselves. /guilded verify off removes it."] = "El c\195\179digo de vinculaci\195\179n con Discord est\195\161 guardado: tus personajes se vinculan autom\195\161ticamente. /guilded verify off lo elimina.",
