local TABLES = { fr = FR, de = DE, es = ES }
local CLIENT_LANGUAGES = { frFR = "fr", deDE = "de", esES = "es", esMX = "es" }

local function language()
  local settings = ns.getSettings and ns.getSettings()
  local chosen = settings and settings.language
  if chosen == "en" or TABLES[chosen] then return chosen end
  return GetLocale and CLIENT_LANGUAGES[GetLocale()] or "en"
end
ns.language = language

-- ns.L("English text") -> text in the player's language (English if no
-- translation exists).
function ns.L(text)
  local translations = TABLES[language()]
  return translations and translations[text] or text
end

ns.commandHandlers = ns.commandHandlers or {}
ns.commandHandlers["lang"] = function(args)
  local settings = ns.getSettings and ns.getSettings()
  if not settings then return end
  local choice = string.lower(args[1] or "")
  if choice == "fr" or choice == "french" or choice == "francais" then
    settings.language = "fr"
    ns.message(ns.L("Language: French. /reload to update the window."))
  elseif choice == "en" or choice == "english" or choice == "anglais" then
    settings.language = "en"
    ns.message(ns.L("Language: English. /reload to update the window."))
  elseif choice == "de" or choice == "deutsch" or choice == "german" then
    settings.language = "de"
    ns.message(ns.L("Language: German. /reload to update the window."))
  elseif choice == "es" or choice == "espanol" or choice == "spanish" then
    settings.language = "es"
    ns.message(ns.L("Language: Spanish. /reload to update the window."))
  elseif choice == "auto" then
    settings.language = nil
    ns.message(ns.L("Language follows your game client. /reload to update the window."))
  else
    ns.message("/guilded lang en | fr | de | es | auto   (now: " .. language() .. ")")
  end
end
ns.commandHelp = ns.commandHelp or {}
table.insert(ns.commandHelp, "/guilded lang en|fr|de|es|auto - language / langue / Sprache / idioma")

